/* ============================================================
   TEST PAGE 5 — THE PERFUMERS IN SECTION (2026-11-06).

   The owner: "please also generate a 5th test page ... modelled like the
   image attached (architecture sketch) that is going to be another page
   that attempts to house the perfumer information." The picture: a long
   section through a building on black, drawn in white pencil and chalk —
   a jagged roofline traced over heavily, the rooms in fine lines, the
   ground ruled across, an "elastic" form hanging below it with its levels
   marked (−0.05, −0.10 …), construction lines crossing it all, notes in a
   hand down the left, small plans in a corner, details boxed at the foot,
   a title in a box at the top left.

   Here the section is THE PERFUMERS' HOUSES, built: ABOVE GROUND every house
   a bay, as wide as the perfumes its perfumer made for it — a bay for each
   perfumer a house was made by — a stud in it for every perfume, AS TALL AS
   ITS YEAR (a stub, dashed, where none is found), the roof over it as steep
   as the bay is full, the one roofline traced over across all of them;
   BELOW GROUND every perfumer the elastic form under their houses, AS DEEP
   AS WHAT THEY MADE, its level marked (−0.139: a hundred and thirty-nine
   perfumes), piles down to it from each of its bays; a house made by more
   than one perfumer is joined over its roofs. The notes down the left say
   how to read it; the plan at the top right is what is chosen, seen from
   above; the details at the foot are its perfumes.

   Pointed at, a bay, a stud or a perfumer's form is traced again, its lines
   boiling as a sketch does; pressed, it is chosen. The section draws itself
   as the page opens, and a point of chalk goes on retracing the roofline.

   A snapshot of the site's Perfumers ledger, written in above: nothing on
   the site reads this page, and it reads nothing of the site.
   ============================================================ */
(function () {
  "use strict";
  const STILL = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const TAU = Math.PI * 2;
  const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
  const lerp = (a, b, t) => a + (b - a) * t;
  const ease = (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
  function rng(seed) { let s = seed >>> 0; return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296); }
  const hash = (t) => { let h = 2166136261; for (let i = 0; i < t.length; i++) { h ^= t.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; };
  const cmp = (a, b) => String(a).localeCompare(String(b), "en", { sensitivity: "base" });
  const el = (s) => document.querySelector(s);
  const HAND = '"Caveat", "Segoe Print", cursive';

  // ---- THE DATA: a bay for every perfumer and house they made for ------------
  const D = DATA;
  const CREDIT = ["named by a source", "the house's perfumer", "perfumer not found"];
  const PER = D.perfumers.map((p, i) => Object.assign({}, p, { i, list: [], bays: [], none: p.id === "not-found" }));
  PER.forEach((p) => (p.name2 = p.none ? "Perfumer not found" : p.name));
  const HOU = D.houses;
  const byPair = new Map();
  D.perfumes.forEach((r) => r[1].forEach((q) => {
    const e = { n: r[0], q, c: r[2], y: r[3], h: r[4], k: r[5], s: r[6], who: r[1] };
    PER[q].list.push(e);
    const key = q + "|" + r[4];
    if (!byPair.has(key)) byPair.set(key, { p: PER[q], h: r[4], list: [] });
    byPair.get(key).list.push(e);
  }));
  const ORDER = PER.slice().sort((a, b) => (a.none - b.none) || cmp(a.sort, b.sort));
  const BAYS = [];
  ORDER.forEach((p) => {
    Array.from(byPair.values()).filter((b) => b.p === p).sort((a, b) => cmp(HOU[a.h].name, HOU[b.h].name)).forEach((b) => {
      b.list.sort((x, y) => (x.y || 9999) - (y.y || 9999) || cmp(x.n, y.n));
      b.i = BAYS.length; b.name = HOU[b.h].name;
      BAYS.push(b); p.bays.push(b);
    });
  });
  const TOTAL = BAYS.reduce((n, b) => n + b.list.length, 0);

  // ---- THE PAGE ------------------------------------------------------------
  const wrap = el(".t5-scroll"), cv = el(".t5-scene"), ctx = cv.getContext("2d");
  const tip = el(".t5-tip");
  let W = 0, H = 0, DPR = 1, phone = false;
  const L = { x0: 0, x1: 0, ground: 0, unit: 1 };
  let sheet = null;                 // the section drawn once, a picture of its own

  function layout() {
    phone = window.innerWidth < 760;
    W = Math.max(window.innerWidth, phone ? 1240 : 0);
    H = window.innerHeight;
    DPR = Math.min(window.devicePixelRatio || 1, 2);
    cv.width = Math.round(W * DPR); cv.height = Math.round(H * DPR);
    cv.style.width = W + "px"; cv.style.height = H + "px";
    L.x0 = phone ? 78 : Math.max(300, W * 0.205);
    L.x1 = W - (phone ? 40 : 60);
    L.ground = H * (phone ? 0.5 : 0.55);
    L.yearK = (H * (phone ? 0.14 : 0.15)) / (2026 - 2008);
    // the bays: as wide as their perfumes, none narrower than it can be seen
    const minW = 13, gap = 0;
    const span = L.x1 - L.x0;
    let unit = span / TOTAL;
    for (let it = 0; it < 30; it++) {
      let used = 0, fixed = 0;
      BAYS.forEach((b) => { if (b.list.length * unit < minW) fixed += minW; else used += b.list.length; });
      unit = (span - fixed - gap * (BAYS.length - 1)) / Math.max(1, used);
    }
    L.unit = unit;
    let x = L.x0;
    BAYS.forEach((b) => {
      const w = Math.max(minW, b.list.length * unit);
      b.x0 = x; b.x1 = x + w; b.cx = x + w / 2;
      const top = Math.max(...b.list.map((e) => studH(e)));
      b.eave = L.ground - top - 10;
      // a narrow bay a low pitch, a broad one a steep one: the roof as steep
      // as the bay is full
      b.ridge = b.eave - 6 - Math.min(w * 0.5, Math.sqrt(b.list.length) * (phone ? 7 : 9)) - (hash(b.name + b.p.id) % 6);
      x += w + gap;
    });
    // the perfumers' forms below ground, under their bays
    ORDER.forEach((p) => {
      p.x0 = p.bays[0].x0; p.x1 = p.bays[p.bays.length - 1].x1; p.cx = (p.x0 + p.x1) / 2;
      p.depth = 22 + Math.sqrt(p.list.length) * (phone ? 7 : 9.5);
    });
    sheet = null;
  }
  // a stud as tall as its perfume's year (a stub where none is found)
  const studH = (e) => (e.y ? 24 + (e.y - 2008) * L.yearK : 16);

  // ---- PENCIL AND CHALK: every line drawn more than once, a little off ----
  function stroke(c, R, pts, o) {
    const passes = o.passes || 2, jit = o.jit == null ? 1.2 : o.jit, over = o.over == null ? 4 : o.over;
    for (let k = 0; k < passes; k++) {
      c.globalAlpha = (o.alpha || 0.7) * (k ? 0.55 : 1);
      c.lineWidth = (o.width || 1) * (k ? 0.7 : 1);
      c.beginPath();
      for (let i = 0; i < pts.length; i++) {
        let [x, y] = pts[i];
        // the pencil runs a little past the ends, as an architect's does
        if (over && (i === 0 || i === pts.length - 1) && pts.length > 1) {
          const [ax, ay] = i === 0 ? pts[1] : pts[i - 1];
          const d = Math.hypot(x - ax, y - ay) || 1;
          const f = (R() * over) / d;
          x += (x - ax) * f; y += (y - ay) * f;
        }
        x += (R() - 0.5) * jit * 2; y += (R() - 0.5) * jit * 2;
        if (!i) c.moveTo(x, y); else c.lineTo(x, y);
      }
      c.stroke();
    }
  }
  // chalk: a line built of many short rough strokes and specks
  function chalk(c, R, pts, width, alpha) {
    for (let i = 0; i < pts.length - 1; i++) {
      const [x0, y0] = pts[i], [x1, y1] = pts[i + 1];
      const d = Math.hypot(x1 - x0, y1 - y0), n = Math.max(2, Math.ceil(d / 3));
      for (let j = 0; j < n; j++) {
        const t = j / n, x = lerp(x0, x1, t), y = lerp(y0, y1, t);
        for (let k = 0; k < 3; k++) {
          c.globalAlpha = alpha * (0.35 + R() * 0.65);
          const s = width * (0.4 + R() * 0.9);
          c.fillRect(x + (R() - 0.5) * width * 1.6, y + (R() - 0.5) * width * 1.6, s, s);
        }
      }
    }
  }
  // the roofline: one line across every bay — its walls, its eaves, its ridge
  function rooflinePts() {
    const pts = [];
    BAYS.forEach((b, i) => {
      const prev = BAYS[i - 1];
      if (!prev || Math.abs(prev.eave - b.eave) > 0.5) pts.push([b.x0, b.eave]);
      pts.push([b.cx, b.ridge], [b.x1, b.eave]);
    });
    return pts;
  }
  // a perfumer's form below ground: elastic, hanging from the ground line
  function formPts(p) {
    const pts = [], n = 28, wob = (hash(p.id) % 100) / 100;
    for (let i = 0; i <= n; i++) {
      const t = i / n, x = lerp(p.x0 + 2, p.x1 - 2, t);
      const sag = Math.pow(Math.sin(Math.PI * t), 0.8);
      const y = L.ground + 6 + sag * p.depth * (1 + 0.12 * Math.sin(t * 9 + wob * 6)) ;
      pts.push([x, y]);
    }
    return pts;
  }

  // ---- THE SHEET: everything that stands still, drawn once -------------------
  function drawSheet() {
    const c = document.createElement("canvas");
    c.width = cv.width; c.height = cv.height;
    const x = c.getContext("2d");
    x.scale(DPR, DPR);
    x.fillStyle = "#050505"; x.fillRect(0, 0, W, H);
    const R = rng(51106);
    x.strokeStyle = "#f2f2ee"; x.fillStyle = "#f2f2ee";
    x.lineCap = "round"; x.lineJoin = "round";
    // the masses behind, faint, as the picture's
    for (let i = 0; i < 7; i++) {
      const bx = lerp(L.x0, L.x1, R()), bw = 60 + R() * 200, bh = 80 + R() * 160;
      x.globalAlpha = 0.05 + R() * 0.05; x.fillStyle = "#3a3a3a";
      x.fillRect(bx, L.ground - bh - 40 - R() * 60, bw, bh);
    }
    x.fillStyle = "#f2f2ee";
    // construction lines, crossing it all
    for (let i = 0; i < 34; i++) {
      const a = BAYS[Math.floor(R() * BAYS.length)], b = ORDER[Math.floor(R() * ORDER.length)];
      stroke(x, R, [[a.cx + (R() - 0.5) * 30, a.ridge - R() * 30], [b.cx + (R() - 0.5) * 40, L.ground + b.depth * (0.4 + R() * 0.8)]], { alpha: 0.08 + R() * 0.08, width: 0.6, passes: 1, over: 40 });
    }
    // the ground, ruled across, a little beyond the section each side
    stroke(x, R, [[L.x0 - 50, L.ground], [L.x1 + 30, L.ground]], { alpha: 0.75, width: 1.2, passes: 3, jit: 0.8, over: 20 });
    stroke(x, R, [[L.x0 - 40, L.ground + 5], [L.x1 + 20, L.ground + 5]], { alpha: 0.25, width: 0.6, passes: 1 });
    // THE BAYS: walls, floors, studs, braces, a mark at each stud's top
    BAYS.forEach((b) => {
      const w = b.x1 - b.x0;
      stroke(x, R, [[b.x0, L.ground], [b.x0, b.eave]], { alpha: 0.5, width: 0.8 });
      stroke(x, R, [[b.x1, L.ground], [b.x1, b.eave]], { alpha: 0.5, width: 0.8 });
      // floors
      for (let y = L.ground - 34; y > b.eave + 6; y -= 34) stroke(x, R, [[b.x0, y], [b.x1, y]], { alpha: 0.16, width: 0.6, passes: 1, over: 2 });
      // a brace now and then
      if (w > 30 && R() < 0.7) stroke(x, R, [[b.x0 + 2, L.ground - 2], [b.x1 - 2, b.eave + 4]], { alpha: 0.14, width: 0.6, passes: 1 });
      // the studs: a perfume each, as tall as its year
      b.list.forEach((e, k) => {
        const sx = b.x0 + ((k + 0.5) / b.list.length) * w;
        e.sx = sx; e.sy = L.ground - studH(e); e.bay = b;
        if (e.y) stroke(x, R, [[sx, L.ground], [sx, e.sy]], { alpha: 0.42, width: 0.7, passes: 1, over: 2, jit: 0.5 });
        else { x.setLineDash([2, 3]); stroke(x, R, [[sx, L.ground], [sx, e.sy]], { alpha: 0.45, width: 0.7, passes: 1, over: 0, jit: 0.3 }); x.setLineDash([]); }
        // its mark: a dot where a source names its perfumer, a ring for the
        // house's perfumer, a cross where none is found
        x.globalAlpha = 0.85;
        if (e.c === 0) { x.beginPath(); x.arc(sx, e.sy, 1.6, 0, TAU); x.fill(); }
        else if (e.c === 1) { x.lineWidth = 0.8; x.beginPath(); x.arc(sx, e.sy, 2.2, 0, TAU); x.stroke(); }
        else { x.lineWidth = 0.8; x.beginPath(); x.moveTo(sx - 2, e.sy - 2); x.lineTo(sx + 2, e.sy + 2); x.moveTo(sx + 2, e.sy - 2); x.lineTo(sx - 2, e.sy + 2); x.stroke(); }
      });
      // its roof, inside the roofline: the two pitches drawn fine
      stroke(x, R, [[b.x0, b.eave], [b.cx, b.ridge], [b.x1, b.eave]], { alpha: 0.35, width: 0.7, passes: 1 });
    });
    // the roofline traced over heavily in chalk, as the picture's
    const roof = rooflinePts();
    chalk(x, R, roof, phone ? 2 : 2.6, 0.75);
    stroke(x, R, roof, { alpha: 0.9, width: 1.4, passes: 2, jit: 1 });
    // a house made by more than one perfumer, joined over its roofs
    const byHouse = new Map();
    BAYS.forEach((b) => { if (!byHouse.has(b.h)) byHouse.set(b.h, []); byHouse.get(b.h).push(b); });
    x.setLineDash([3, 4]);
    byHouse.forEach((list) => {
      for (let i = 1; i < list.length; i++) {
        const a = list[0], b = list[i], top = Math.min(a.ridge, b.ridge) - 26 - i * 8;
        x.globalAlpha = 0.35; x.lineWidth = 0.7;
        x.beginPath(); x.moveTo(a.cx, a.ridge - 4); x.bezierCurveTo(a.cx, top, b.cx, top, b.cx, b.ridge - 4); x.stroke();
      }
    });
    x.setLineDash([]);
    // THE PERFUMERS below ground: the elastic form, piles from its bays, hatched
    ORDER.forEach((p) => {
      const pts = formPts(p);
      // hatched inside
      x.save();
      x.beginPath(); x.moveTo(p.x0, L.ground + 4); pts.forEach(([px, py]) => x.lineTo(px, py)); x.lineTo(p.x1, L.ground + 4); x.closePath(); x.clip();
      x.globalAlpha = 0.12; x.lineWidth = 0.6;
      x.beginPath();
      for (let hx = p.x0 - 200; hx < p.x1 + 20; hx += 7) { x.moveTo(hx, L.ground + 200); x.lineTo(hx + 200, L.ground); }
      x.stroke();
      x.restore();
      chalk(x, R, pts, phone ? 1.4 : 1.8, 0.5);
      stroke(x, R, pts, { alpha: 0.75, width: 1, passes: 2, jit: 1.2 });
      // the piles, down from each of its bays
      p.bays.forEach((b) => stroke(x, R, [[b.cx, L.ground], [b.cx + (R() - 0.5) * 6, L.ground + 6 + p.depth * 0.9]], { alpha: 0.3, width: 0.6, passes: 1 }));
      // its level, as the picture marks them: −0.139 for a hundred and thirty-nine
      const lv = "−" + (p.list.length / 1000).toFixed(3).replace(/^0/, "0");
      if (p.x1 - p.x0 > 30) {
        x.globalAlpha = 0.85;
        x.font = "400 " + (phone ? 12 : 14) + "px " + HAND;
        x.textAlign = "center"; x.textBaseline = "top";
        x.fillText(lv, p.cx, L.ground + 12 + p.depth + 4);
        stroke(x, R, [[p.cx - 14, L.ground + 10 + p.depth], [p.cx + 14, L.ground + 10 + p.depth]], { alpha: 0.6, width: 0.7, passes: 1 });
      }
      // and its name, where there is room
      if (p.x1 - p.x0 > 44) {
        x.globalAlpha = 0.6;
        x.font = "400 " + (phone ? 12 : 14) + "px " + HAND;
        x.fillText(p.name2.toLowerCase(), p.cx, L.ground + 30 + p.depth + 4);
      }
    });
    // the houses' names over their roofs, where there is room, slanting up
    x.textAlign = "left"; x.textBaseline = "alphabetic";
    BAYS.forEach((b) => {
      if (b.x1 - b.x0 < 34) return;
      x.save();
      x.translate(b.cx - 4, b.ridge - 10);
      x.rotate(-0.42);
      x.globalAlpha = 0.72;
      x.font = "400 " + (phone ? 13 : 15) + "px " + HAND;
      x.fillText(b.name.toLowerCase(), 0, 0);
      x.restore();
    });
    // the years up the left of the section, a dimension line
    x.globalAlpha = 0.55; x.font = "400 13px " + HAND; x.textAlign = "right"; x.textBaseline = "middle";
    const yx = L.x0 - 14;
    stroke(x, R, [[yx, L.ground], [yx, L.ground - 30 - 18 * L.yearK]], { alpha: 0.5, width: 0.7, passes: 1 });
    [2010, 2014, 2018, 2022, 2026].forEach((y) => {
      const yy = L.ground - 30 - (y - 2008) * L.yearK;
      stroke(x, R, [[yx - 4, yy], [yx + 4, yy]], { alpha: 0.6, width: 0.7, passes: 1, over: 0 });
      x.globalAlpha = 0.55; x.fillText(String(y), yx - 8, yy);
    });
    x.globalAlpha = 0.55; x.fillText("± 0.000", yx - 8, L.ground + 1);
    // the strategy's name under it all, in the hand, as the picture's
    x.textAlign = "center"; x.textBaseline = "alphabetic";
    x.globalAlpha = 0.85; x.font = "500 " + (phone ? 20 : 26) + "px " + HAND;
    const deepest = Math.max(...ORDER.map((p) => p.depth));
    const sy = Math.min(H - 40, L.ground + deepest + (phone ? 70 : 84));
    x.fillText("ELASTIC HOUSING STRATEGY.", (L.x0 + L.x1) / 2, sy);
    stroke(x, R, [[(L.x0 + L.x1) / 2 - 130, sy + 8], [(L.x0 + L.x1) / 2 + 130, sy + 6]], { alpha: 0.5, width: 0.8, passes: 2 });
    x.globalAlpha = 1;
    return c;
  }

  // ---- WHAT IS CHOSEN, AND POINTED AT ---------------------------------------
  let hover = null, chosen = null;       // { kind: "bay"|"per"|"perfume", ... }
  const same = (a, b) => (!a && !b) || (a && b && a.kind === b.kind && (a.b || a.p || a.e) === (b.b || b.p || b.e));
  function at(mx, my) {
    // a stud
    if (my < L.ground + 2) {
      for (const b of BAYS) {
        if (mx < b.x0 - 2 || mx > b.x1 + 2) continue;
        // a perfume by the mark at its stud's top; anywhere else in the bay, the bay
        let best = null, bd = 9;
        for (const e of b.list) { const d = Math.hypot(e.sx - mx, (e.sy - my) * 0.8); if (d < bd) { bd = d; best = e; } }
        if (best) return { kind: "perfume", e: best, b };
        if (my > b.ridge - 14) return { kind: "bay", b };
      }
      return null;
    }
    // a perfumer's form
    for (const p of ORDER) if (mx >= p.x0 && mx <= p.x1 && my <= L.ground + p.depth + 50) return { kind: "per", p };
    return null;
  }
  function tipFor(s) {
    if (s.kind === "perfume") {
      const e = s.e;
      return "<b>" + esc(e.n) + "</b><span>" + esc(HOU[e.h].name) + " · " + (e.y || "year not found") + "</span><span>" + esc(e.who.map((q) => PER[q].name2).join(" & ")) + " — " + CREDIT[e.c] + "</span>";
    }
    if (s.kind === "bay") {
      const b = s.b, ys = b.list.map((e) => e.y).filter(Boolean);
      return "<b>" + esc(b.name) + "</b><span>" + b.list.length + (b.list.length === 1 ? " perfume" : " perfumes") + " by " + esc(b.p.name2) + (ys.length ? " · " + Math.min(...ys) + (Math.max(...ys) > Math.min(...ys) ? "–" + Math.max(...ys) : "") : "") + "</span>";
    }
    const p = s.p;
    return "<b>" + esc(p.name2) + "</b><span>" + p.list.length + " perfumes · " + p.bays.length + (p.bays.length === 1 ? " house" : " houses") + (p.from ? " · " + esc(p.from) : "") + "</span>";
  }
  const local = (ev) => { const r = cv.getBoundingClientRect(); return [ev.clientX - r.left, ev.clientY - r.top]; };
  cv.addEventListener("pointermove", (ev) => {
    if (ev.pointerType === "touch") return;
    const [mx, my] = local(ev);
    const s = at(mx, my);
    if (!same(s, hover)) { hover = s; kick(); }
    if (s) {
      tip.innerHTML = tipFor(s); tip.hidden = false;
      const tw = tip.offsetWidth, th = tip.offsetHeight;
      let px = ev.clientX + 16, py = ev.clientY + 16;
      if (px + tw > window.innerWidth - 8) px = ev.clientX - tw - 16;
      if (py + th > window.innerHeight - 8) py = ev.clientY - th - 16;
      tip.style.transform = "translate(" + Math.round(px) + "px," + Math.round(py) + "px)";
    } else tip.hidden = true;
    cv.style.cursor = s ? "pointer" : "default";
  });
  cv.addEventListener("pointerleave", () => { hover = null; tip.hidden = true; kick(); });
  cv.addEventListener("click", (ev) => { const [mx, my] = local(ev); choose(at(mx, my)); });
  document.addEventListener("keydown", (ev) => { if (ev.key === "Escape") choose(null); });

  // ---- THE DETAILS AT THE FOOT, and the plan at the top right ----------------
  const detail = el(".t5-detail-body");
  function choose(s) {
    chosen = s;
    if (s && s.kind === "perfume") chosen = { kind: "perfume", e: s.e, b: s.b };
    const pick = el(".t5-pick");
    pick.value = s ? String((s.p || s.b.p).i) : "";
    if (!s) {
      detail.innerHTML = '<p class="t5-note">Nothing chosen. ' + (window.matchMedia("(hover: none)").matches ? "Swipe the section sideways; tap a bay, a stud's top or a form below the ground" : "Point at a bay, a stud's top or a form below the ground; press it") + ' to bring its detail here.</p>';
    } else if (s.kind === "per") {
      const p = s.p;
      detail.innerHTML = '<p class="t5-k">Detail · below ground</p><h2>' + esc(p.name2) + "</h2>" +
        '<p class="t5-m">' + [p.from, p.born && "born " + p.born, p.list.length + " perfumes", "level −" + (p.list.length / 1000).toFixed(3)].filter(Boolean).map(esc).join(" · ") + "</p>" +
        (p.about.length ? '<p class="t5-a">' + esc(p.about[0]) + "</p>" : "") +
        "<ul>" + p.bays.map((b) => '<li><button type="button" data-bay="' + b.i + '">' + esc(b.name) + "</button><i>" + b.list.length + "</i></li>").join("") + "</ul>";
    } else {
      const b = s.b;
      const ys = b.list.map((e) => e.y).filter(Boolean);
      const ho = HOU[b.h];
      detail.innerHTML = '<p class="t5-k">Detail · above ground</p><h2>' + esc(b.name) + "</h2>" +
        '<p class="t5-m">by <button type="button" data-per="' + b.p.i + '">' + esc(b.p.name2) + "</button>" + [ho.from, ho.founded && "founded " + ho.founded, b.list.length + " perfumes", ys.length ? Math.min(...ys) + "–" + Math.max(...ys) : ""].filter(Boolean).map((t) => " · " + esc(t)).join("") + "</p>" +
        "<ol>" + b.list.map((e) => '<li class="' + (chosen.e === e ? "is-on" : "") + '"><button type="button" data-e="' + b.list.indexOf(e) + '">' + esc(e.n) + "</button><i>" + (e.y || "—") + "</i></li>").join("") + "</ol>" +
        (chosen.e ? '<p class="t5-a">' + esc(chosen.e.n) + ": " + esc(chosen.e.who.map((q) => PER[q].name2).join(" & ")) + " — " + CREDIT[chosen.e.c] + (chosen.e.s.length ? "; " + chosen.e.s.map((i) => esc(D.sources[i])).join(", ") : "") + ".</p>" : "");
    }
    el(".t5-detail").classList.toggle("is-on", !!s);
    kick();
  }
  detail.addEventListener("click", (ev) => {
    const b = ev.target.closest("[data-bay]"); if (b) { choose({ kind: "bay", b: BAYS[+b.dataset.bay] }); return; }
    const p = ev.target.closest("[data-per]"); if (p) { choose({ kind: "per", p: PER[+p.dataset.per] }); return; }
    const e = ev.target.closest("[data-e]"); if (e && chosen && chosen.b) choose({ kind: "perfume", e: chosen.b.list[+e.dataset.e], b: chosen.b });
  });
  const pick = el(".t5-pick");
  pick.innerHTML = '<option value="">Every perfumer</option>' + ORDER.map((p) => '<option value="' + p.i + '">' + esc(p.name2) + " · " + p.list.length + "</option>").join("");
  pick.addEventListener("change", () => {
    const p = pick.value === "" ? null : PER[+pick.value];
    choose(p ? { kind: "per", p } : null);
    if (p && phone) wrap.scrollTo({ left: Math.max(0, p.cx - window.innerWidth / 2), behavior: STILL ? "auto" : "smooth" });
  });

  // ---- DRAWING ------------------------------------------------------------
  let t0 = -1, clock = 0, last = 0, raf = 0;
  const DRAW_MS = 2600;
  const roofLen = [];
  let roof = [];
  function drawLive(now, t) {
    if (!sheet) { sheet = drawSheet(); roof = rooflinePts(); roofLen.length = 0; let s = 0; roof.forEach((p, i) => { if (i) s += Math.hypot(p[0] - roof[i - 1][0], p[1] - roof[i - 1][1]); roofLen.push(s); }); }
    const c = ctx;
    c.setTransform(1, 0, 0, 1, 0, 0);
    c.fillStyle = "#050505"; c.fillRect(0, 0, cv.width, cv.height);
    // the sheet drawing itself, left to right, a pencil's point at its edge
    const k = STILL ? 1 : clamp((now - t0) / DRAW_MS, 0, 1);
    const reveal = ease(k) * (W + 80) - 40;
    if (k < 1) {
      c.drawImage(sheet, 0, 0, Math.max(1, reveal * DPR), cv.height, 0, 0, Math.max(1, reveal * DPR), cv.height);
    } else c.drawImage(sheet, 0, 0);
    c.setTransform(DPR, 0, 0, DPR, 0, 0);
    c.strokeStyle = "#fff"; c.fillStyle = "#fff"; c.lineCap = "round";
    if (k < 1) {
      c.globalAlpha = 0.7; c.lineWidth = 1;
      c.beginPath(); c.moveTo(reveal, 0); c.lineTo(reveal, H); c.stroke();
      c.globalAlpha = 0.15; c.fillRect(reveal - 14, 0, 14, H);
    }
    // a point of chalk retracing the roofline, over and over
    if (!STILL && k >= 1 && roof.length > 1) {
      const total = roofLen[roofLen.length - 1], s = ((t * 90) % (total + 300)) - 150;
      for (let tail = 0; tail < 14; tail++) {
        const u = s - tail * 3;
        if (u < 0 || u > total) continue;
        let i = 1; while (i < roofLen.length && roofLen[i] < u) i++;
        const a = roof[i - 1], b = roof[Math.min(i, roof.length - 1)], seg = roofLen[i] - roofLen[i - 1] || 1, f = (u - roofLen[i - 1]) / seg;
        c.globalAlpha = (1 - tail / 14) * 0.9;
        c.beginPath(); c.arc(lerp(a[0], b[0], f), lerp(a[1], b[1], f), 2.4 - tail * 0.12, 0, TAU); c.fill();
      }
    }
    // what is pointed at, or chosen: traced again, boiling as a sketch does
    const boil = STILL ? 0 : Math.floor(t * 7);
    for (const s of [chosen, hover]) {
      if (!s) continue;
      const R = rng(boil * 977 + (s === chosen ? 3 : 7));
      const bays = s.kind === "per" ? s.p.bays : [s.b];
      bays.forEach((b) => {
        traceBay(c, R, b, s === chosen ? 1 : 0.8);
        const p = b.p;
        trace(c, R, formPts(p), s === chosen ? 1 : 0.75, 1.3);
      });
      if (s.e) {
        const e = s.e;
        c.globalAlpha = 1; c.lineWidth = 1.6;
        c.beginPath(); c.moveTo(e.sx, L.ground); c.lineTo(e.sx, e.sy); c.stroke();
        c.beginPath(); c.arc(e.sx, e.sy, 5, 0, TAU); c.stroke();
        c.font = "500 16px " + HAND; c.textAlign = "left"; c.textBaseline = "bottom";
        c.fillText(e.n.toLowerCase() + (e.y ? " · " + e.y : ""), e.sx + 8, e.sy - 6);
      }
    }
    // the plan at the top right: what is chosen, seen from above
    drawPlan(c, t);
    c.globalAlpha = 1;
  }
  function trace(c, R, pts, alpha, width) {
    for (let k = 0; k < 2; k++) {
      c.globalAlpha = alpha * (k ? 0.5 : 0.95); c.lineWidth = width * (k ? 0.7 : 1);
      c.beginPath();
      pts.forEach(([x, y], i) => { const px = x + (R() - 0.5) * 2.4, py = y + (R() - 0.5) * 2.4; if (!i) c.moveTo(px, py); else c.lineTo(px, py); });
      c.stroke();
    }
  }
  function traceBay(c, R, b, alpha) {
    trace(c, R, [[b.x0, L.ground], [b.x0, b.eave], [b.cx, b.ridge], [b.x1, b.eave], [b.x1, L.ground]], alpha, 1.6);
    c.globalAlpha = alpha * 0.9; c.lineWidth = 1;
    c.beginPath();
    b.list.forEach((e) => { c.moveTo(e.sx + (R() - 0.5) * 1.5, L.ground); c.lineTo(e.sx + (R() - 0.5) * 1.5, e.sy); });
    c.stroke();
    c.font = "500 16px " + HAND; c.textAlign = "center"; c.textBaseline = "bottom"; c.globalAlpha = alpha;
    c.fillText(b.name.toLowerCase(), b.cx, b.ridge - 12);
  }
  // a plan of the chosen, from above: its bays round a circle, every perfume
  // a radial line as long as its year — the picture's plans in the corner
  function drawPlan(c, t) {
    const r = phone ? 44 : 58;
    const cx = (phone ? window.innerWidth : W) - (phone ? 60 : 96) + (phone ? wrap.scrollLeft : 0), cy = phone ? 118 : 118;
    const s = chosen || hover;
    const bays = !s ? BAYS : s.kind === "per" ? s.p.bays : [s.b];
    const list = [];
    bays.forEach((b) => b.list.forEach((e) => list.push(e)));
    const turn = STILL ? 0 : t * 0.05;
    c.globalAlpha = 0.6; c.lineWidth = 0.8; c.strokeStyle = "#fff";
    c.beginPath(); c.arc(cx, cy, r * 0.32, 0, TAU); c.stroke();
    c.globalAlpha = 0.25;
    c.beginPath(); c.arc(cx, cy, r, 0, TAU); c.stroke();
    c.globalAlpha = 0.5;
    c.beginPath();
    list.forEach((e, i) => {
      const a = turn + (i / list.length) * TAU;
      const len = r * (0.36 + (e.y ? (e.y - 2008) / 18 : 0.05) * 0.62);
      c.moveTo(cx + Math.cos(a) * r * 0.34, cy + Math.sin(a) * r * 0.34);
      c.lineTo(cx + Math.cos(a) * len, cy + Math.sin(a) * len);
    });
    c.stroke();
    // a tick where each bay begins
    let k = 0;
    c.globalAlpha = 0.8;
    c.beginPath();
    bays.forEach((b) => { const a = turn + (k / list.length) * TAU; c.moveTo(cx + Math.cos(a) * r * 0.9, cy + Math.sin(a) * r * 0.9); c.lineTo(cx + Math.cos(a) * r * 1.08, cy + Math.sin(a) * r * 1.08); k += b.list.length; });
    c.stroke();
    c.font = "400 15px " + HAND; c.textAlign = "center"; c.textBaseline = "top"; c.globalAlpha = 0.7;
    c.fillText(!s ? "plan · all " + TOTAL : (s.kind === "per" ? s.p.name2 : s.b.name).toLowerCase() + " · " + list.length, cx, cy + r + 10);
  }

  function frame(now) {
    raf = 0;
    const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60;
    last = now;
    if (!STILL) clock += dt;
    if (t0 < 0) t0 = now;
    drawLive(now, clock);
    if (!STILL && !document.hidden) raf = requestAnimationFrame(frame);
    else last = 0;
  }
  function kick() { if (!raf) raf = requestAnimationFrame(frame); }
  document.addEventListener("visibilitychange", () => { if (!document.hidden) { last = 0; kick(); } });
  wrap.addEventListener("scroll", kick, { passive: true });
  let rq = 0;
  window.addEventListener("resize", () => { if (rq) return; rq = requestAnimationFrame(() => { rq = 0; layout(); kick(); }); });
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(() => { sheet = null; kick(); });
  if (STILL) ["click", "keydown", "change", "pointermove"].forEach((e) => document.addEventListener(e, () => requestAnimationFrame(frame)));

  // the grain, a picture of noise jumped about by its transform
  (function grain() {
    const g = document.createElement("canvas");
    g.width = g.height = 160;
    const x = g.getContext("2d"), im = x.createImageData(160, 160), R = rng(5);
    for (let i = 0; i < im.data.length; i += 4) { const v = R() * 255; im.data[i] = im.data[i + 1] = im.data[i + 2] = v; im.data[i + 3] = 255; }
    x.putImageData(im, 0, 0);
    el(".t5-grain").style.backgroundImage = "url(" + g.toDataURL() + ")";
  })();

  layout();
  choose(null);
  kick();
  window.TestPage5 = {
    bays: BAYS.length, perfumers: ORDER.length, perfumes: TOTAL,
    bayAt: (house, perfumer) => { const b = BAYS.find((x) => HOU[x.h].id === house && (!perfumer || x.p.id === perfumer)); const r = cv.getBoundingClientRect(); return b ? { x: r.left + b.cx, y: r.top + L.ground - 8, w: b.x1 - b.x0, n: b.list.length } : null; },
    studAt: (name) => { for (const b of BAYS) for (const e of b.list) if (e.n === name) { const r = cv.getBoundingClientRect(); return { x: r.left + e.sx, y: r.top + e.sy }; } return null; },
    formAt: (id) => { const p = PER.find((x) => x.id === id); const r = cv.getBoundingClientRect(); return p ? { x: r.left + p.cx, y: r.top + L.ground + p.depth * 0.5, depth: p.depth } : null; },
    studOf: (name) => { for (const b of BAYS) for (const e of b.list) if (e.n === name) return { h: L.ground - e.sy, y: e.y }; return null; },
    chosen: () => (chosen ? { kind: chosen.kind, name: chosen.kind === "per" ? chosen.p.name2 : chosen.kind === "bay" ? chosen.b.name : chosen.e.n } : null),
  };
})();
